import { spawnSync } from 'node:child_process';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const OPA_IMAGE = 'openpolicyagent/opa:1.20.2';
const CATALOG_QUERY =
  'data.campuspilot.authorization.catalog.generation_manifest';
const GENERATED_HEADER = `// Generated by scripts/generate-actions.mjs from the Rego permission catalog.
// Do not edit this file directly. Run \`pnpm generate:actions\`.
`;
const resourceKinds = ['system', 'school', 'class'];
const resourceTypeByKind = {
  system: 'SystemResource',
  school: 'SchoolResource',
  class: 'ClassResource',
};

const packageDirectory = join(dirname(fileURLToPath(import.meta.url)), '..');
const policiesDirectory = join(packageDirectory, 'src', 'policies');
const checkOnly = process.argv.includes('--check');

function fail(message) {
  throw new Error(`Permission action generation failed: ${message}`);
}

function evaluateCatalog() {
  const result = spawnSync(
    'docker',
    [
      'run',
      '--rm',
      '-v',
      `${policiesDirectory}:/policies:ro`,
      OPA_IMAGE,
      'eval',
      '--format=raw',
      '--data',
      '/policies',
      CATALOG_QUERY,
    ],
    { encoding: 'utf8', maxBuffer: 10 * 1024 * 1024 },
  );

  if (result.error) {
    fail(`could not start Docker: ${result.error.message}`);
  }
  if (result.status !== 0) {
    fail(result.stderr.trim() || `OPA exited with status ${result.status}`);
  }

  try {
    return JSON.parse(result.stdout);
  } catch (error) {
    fail(`OPA returned invalid JSON: ${error.message}`);
  }
}

function validateCatalog(value) {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    fail('the evaluated catalog manifest must be an object');
  }

  const { actions: declarations, grants } = value;
  if (!Array.isArray(declarations)) fail('manifest.actions must be an array');
  if (!Array.isArray(grants)) fail('manifest.grants must be an array');

  const actions = new Map();
  const keysByKind = new Map(
    resourceKinds.map((resourceKind) => [resourceKind, new Map()]),
  );

  for (const [index, declaration] of declarations.entries()) {
    if (typeof declaration !== 'object' || declaration === null) {
      fail(`declaration ${index} must be an object`);
    }

    const { id, key, resourceKind } = declaration;
    for (const [field, fieldValue] of Object.entries({
      id,
      key,
      resourceKind,
    })) {
      if (typeof fieldValue !== 'string' || fieldValue.length === 0) {
        fail(`declaration ${index} has an invalid ${field}`);
      }
    }

    if (!resourceKinds.includes(resourceKind)) {
      fail(`action ${id} has unsupported resourceKind ${resourceKind}`);
    }
    if (!/^[A-Z][A-Z0-9_]*$/.test(key)) {
      fail(`action ${id} has invalid TypeScript key ${key}`);
    }
    if (!/^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*){2,}$/.test(id)) {
      fail(`action ${id} does not follow the dotted action convention`);
    }
    if (!id.startsWith(`${resourceKind}.`)) {
      fail(`action ${id} conflicts with resourceKind ${resourceKind}`);
    }

    const existingAction = actions.get(id);
    if (
      existingAction &&
      (existingAction.key !== key ||
        existingAction.resourceKind !== resourceKind)
    ) {
      fail(`action ${id} has conflicting key or resourceKind declarations`);
    }

    const kindKeys = keysByKind.get(resourceKind);
    const existingKeyAction = kindKeys.get(key);
    if (existingKeyAction && existingKeyAction !== id) {
      fail(
        `${resourceKind} key ${key} is shared by ${existingKeyAction} and ${id}`,
      );
    }

    actions.set(id, { id, key, resourceKind });
    kindKeys.set(key, id);
  }

  if (actions.size === 0) fail('the catalog contains no actions');

  for (const [index, grant] of grants.entries()) {
    if (typeof grant !== 'object' || grant === null) {
      fail(`grant ${index} must be an object`);
    }

    const { role, action } = grant;
    if (typeof role !== 'string' || role.length === 0) {
      fail(`grant ${index} has an invalid role`);
    }
    if (typeof action !== 'string' || action.length === 0) {
      fail(`grant ${index} has an invalid action`);
    }
    if (!/^(platform|school)\.[a-z][a-z0-9_]*$/.test(role)) {
      fail(`grant ${index} has invalid namespaced role ${role}`);
    }
    if (!actions.has(action)) {
      fail(`grant ${index} references undeclared action ${action}`);
    }
  }

  return [...actions.values()].sort((left, right) =>
    left.id.localeCompare(right.id),
  );
}

function capitalize(value) {
  return `${value[0].toUpperCase()}${value.slice(1)}`;
}

function renderActionFile(resourceKind, actions) {
  const variableName = `${resourceKind.toUpperCase()}_ACTIONS`;
  const typeName = `${capitalize(resourceKind)}Action`;
  const properties = actions
    .filter((action) => action.resourceKind === resourceKind)
    .sort((left, right) => left.key.localeCompare(right.key))
    .map((action) => `  ${action.key}: '${action.id}',`)
    .join('\n');

  return `${GENERATED_HEADER}\nexport const ${variableName} = {\n${properties}\n} as const;\n\nexport type ${typeName} =\n  (typeof ${variableName})[keyof typeof ${variableName}];\n`;
}

function renderActionIndex() {
  const imports = resourceKinds
    .map(
      (resourceKind) =>
        `import { ${resourceKind.toUpperCase()}_ACTIONS } from './${resourceKind}';`,
    )
    .join('\n');
  const exports = resourceKinds
    .map(
      (resourceKind) =>
        `export { ${resourceKind.toUpperCase()}_ACTIONS, type ${capitalize(resourceKind)}Action } from './${resourceKind}';`,
    )
    .join('\n');
  const groupedActions = resourceKinds
    .map(
      (resourceKind) =>
        `  ${resourceKind.toUpperCase()}: ${resourceKind.toUpperCase()}_ACTIONS,`,
    )
    .join('\n');

  return `${GENERATED_HEADER}\n${imports}\n\n${exports}\n\n/** Actions are grouped by their declared resource kind. */\nexport const AUTHORIZATION_ACTIONS = {\n${groupedActions}\n} as const;\n`;
}

function renderResourceFile(actions) {
  const imports = resourceKinds
    .map(
      (resourceKind) =>
        `import { ${resourceKind.toUpperCase()}_ACTIONS } from './${resourceKind}';`,
    )
    .join('\n');
  const entries = actions
    .map(
      ({ key, resourceKind }) =>
        `  [${resourceKind.toUpperCase()}_ACTIONS.${key}]: ${resourceTypeByKind[resourceKind]};`,
    )
    .join('\n');

  return `${GENERATED_HEADER}\n${imports}\n\nexport type SystemResource = {\n  kind: 'system';\n};\n\nexport type SchoolResource = {\n  kind: 'school';\n  schoolId: string;\n};\n\nexport type ClassResource = {\n  kind: 'class';\n  schoolId: string;\n  classId: string;\n};\n\nexport type AuthorizationResourceByAction = {\n${entries}\n};\n\nexport type AuthorizationAction = keyof AuthorizationResourceByAction;\n`;
}

function outputFiles(actions) {
  const files = new Map();
  for (const resourceKind of resourceKinds) {
    files.set(
      join(packageDirectory, 'src', 'generated', `${resourceKind}.ts`),
      renderActionFile(resourceKind, actions),
    );
  }
  files.set(
    join(packageDirectory, 'src', 'generated', 'index.ts'),
    renderActionIndex(),
  );
  files.set(
    join(packageDirectory, 'src', 'generated', 'resource.ts'),
    renderResourceFile(actions),
  );
  return files;
}

function updateFiles(files) {
  const staleFiles = [];

  for (const [filePath, expected] of files) {
    let current;
    try {
      current = readFileSync(filePath, 'utf8');
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }

    if (current === expected) continue;
    staleFiles.push(relative(packageDirectory, filePath));
    if (!checkOnly) {
      mkdirSync(dirname(filePath), { recursive: true });
      writeFileSync(filePath, expected);
    }
  }

  if (checkOnly && staleFiles.length > 0) {
    fail(
      `generated files are stale: ${staleFiles.join(', ')}. Run pnpm generate:actions.`,
    );
  }

  if (!checkOnly) {
    const message =
      staleFiles.length === 0
        ? 'Permission action files are already current.'
        : `Generated ${staleFiles.join(', ')}.`;
    process.stdout.write(`${message}\n`);
  }
}

const catalog = evaluateCatalog();
const actions = validateCatalog(catalog);
updateFiles(outputFiles(actions));
